ROOT.scriptdef:
SET NOCOUNT ON;
if exists (select * from sys.columns where  object_id = OBJECT_ID(N'CDN.Sent') and name = 'SnT_StawkaVatWdr') and exists (select * from sys.columns where  object_id = OBJECT_ID(N'CDN.Sent') and name = 'SnT_FlagaVatWdr')
begin
	declare @sql varchar(100)

	set @sql = 'update CDN.Sent set SnT_StawkaVat = SnT_StawkaVatWdr, SnT_FlagaVat = SnT_FlagaVatWdr'
	exec(@sql)

	set @sql = 'alter table CDN.Sent drop column SnT_StawkaVatWdr, SnT_FlagaVatWdr'
	exec(@sql)
end
SET NOCOUNT OFF;
